    pages: {
      abandoned: { title: "Commandes abandonnées", about: "Activé, un brouillon de commande est gardé dès que l'acheteur commence à remplir le formulaire. S'il part sans terminer, la commande reste « abandonnée » dans Commandes : vous pouvez l'appeler et récupérer la vente.", enable: "Suivre les commandes abandonnées", enableHint: "Garder un brouillon quand l'acheteur commence le formulaire." },
      fakeGuard: { title: "Protection anti-fausses commandes", about: "La protection surveille les commandes et refuse l'activité suspecte : trop de commandes d'un même numéro, doublons, robots et numéros qui ont déjà refusé des livraisons." },
      agentAssign: { title: "Attribution aux agents", about: "Les nouvelles commandes arrivent automatiquement à vos agents, selon la méthode choisie. Un agent ne voit que ses commandes." },
      blacklist: { title: "Liste noire", about: "Les numéros et adresses IP bloqués ne peuvent pas commander. Ajoutez des numéros ici ou depuis la fenêtre de commande ; la liste noire reste active même si la protection est arrêtée." },
      trustBadges: { title: "Badges de confiance", about: "Les badges s'affichent sur la page produit sous le formulaire de commande et rassurent l'acheteur." },
      quickContact: { title: "Boutons de contact rapide", about: "Boutons téléphone et WhatsApp flottants sur toutes les pages, pour que le client vous joigne en un geste." },
      thankYou: { title: "Page de remerciement", about: "Après la commande, l'acheteur voit la page de remerciement avec le numéro et le montant. Personnalisez son message et son bouton." },
      qrCode: { title: "Générateur de QR code", about: "Créez des QR codes de qualité pour vos campagnes — boîtes, flyers, autocollants — vers votre boutique, un produit ou un lien." },
      productImport: { title: "Import de produits", about: "Prévisualisez les produits d'une boutique Shopify ou YouCan, puis importez ceux que vous choisissez, avec photos et descriptions, en brouillon." },
      parcelScanner: { title: "Scanner de colis", about: "Scannez l'étiquette avec un lecteur ou la caméra du téléphone : une commande confirmée passe en livraison, un retour revient en stock. Activé, Scanner apparaît dans le menu et sur la page Commandes.", enable: "Activer le scanner de colis", enableHint: "Affiche Scanner dans le menu et le bouton sur Commandes.", open: "Ouvrir le scanner" },
      orderTracking: { title: "Suivi de commande", about: "Après la commande, l'acheteur reçoit un lien privé pour suivre sa commande : reçue, confirmée, en route, livrée, avec le numéro de suivi. Il peut aussi la retrouver depuis la page « Suivre ma commande » de la boutique." },
      whatsapp: { title: "Confirmation des commandes par WhatsApp", about: "À chaque nouvelle commande, l'acheteur reçoit un message WhatsApp pour la confirmer ou l'annuler d'un bouton. Sa réponse apparaît comme un filtre sous les onglets de statut : votre équipe sait qui a confirmé avant d'appeler." },
      promotions: { title: "Campagnes promotionnelles", about: "Choisissez une remise, des produits et des dates : pendant la campagne le nouveau prix s'affiche dans la boutique et les landing pages avec l'ancien barré, et la commande est facturée à ce prix (les offres de quantité baissent du même pourcentage). À la fin, les prix reviennent seuls." },
      collections: { title: "Collections", about: "Regroupez vos produits sous un lien /collections/<nom> (ex. : vêtements, chaussures, soldes). Les collections d'un produit se choisissent sur sa page ; une collection peut être dans une autre (deux niveaux au plus)." },
      deliveryAssign: { title: "Attribution aux livreurs", about: "Définissez des règles qui choisissent la société de livraison de chaque commande selon la wilaya, le montant et le type de livraison. Les règles sont lues dans l'ordre et la première qui correspond s'applique. La société définie sur le produit passe avant." },
      customFields: { title: "Champs personnalisés", about: "Activé, vous pouvez ajouter des questions à chaque produit depuis sa page (onglet Commande et livraison) ; elles s'affichent dans le formulaire et sont gardées avec la commande. Désactivé, elles sont masquées sans être supprimées.", enable: "Activer les champs personnalisés", enableHint: "Affiche l'éditeur de questions sur les produits et les pose dans la boutique." },
      wholesale: { title: "Vente en gros", about: "Activée, chaque produit peut avoir des paliers de prix par quantité et un minimum de commande : le palier atteint fixe le prix de chaque pièce. Réglez-les dans l'onglet « Gros » du produit. Désactivée, ils sont masqués sans être supprimés.", enable: "Activer les prix de gros", enableHint: "Affiche l'onglet Gros dans l'éditeur et applique paliers et minimum dans la boutique." },
      cart: { title: "Panier", about: "Activé, l'acheteur peut mettre plusieurs produits dans un panier et commander une fois : vous recevez une seule commande avec tous les produits. Désactivé par défaut : le panier ajoute une étape ; si vos pubs mènent vers un seul produit, vous préférerez peut-être le laisser désactivé.", enable: "Activer le panier", enableHint: "Ajoute « Ajouter au panier » à côté du bouton de commande, et une icône panier dans la boutique." },
      payments: { title: "Paiement en ligne", about: "L'acheteur paie sa commande en ligne avec le moyen qu'il choisit. Chaque moyen est séparé et relié à votre propre compte : l'argent vous arrive directement. Aucun moyen n'est proposé aux acheteurs avant d'être connecté et testé avec succès. Si le paiement n'aboutit pas, la commande reste en paiement à la livraison." },
      webhook: { title: "Webhook", about: "Chaque nouvelle commande et chaque changement de statut est envoyé à votre URL en JSON signé (X-Scaleitto-Signature)." },
    },
